def choose_move(observation):
    # Extract fields with defaults
    grid = observation.get('grid', [])
    position = observation.get('position', (0, 0))
    mode = observation.get('mode', None)
    resources = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    territory_map = observation.get('territory', [])
    width = observation.get('width', len(grid[0]) if grid else 0)
    height = observation.get('height', len(grid))
    x, y = position

    def is_valid(pos):
        nx, ny = pos
        if 0 <= nx < width and 0 <= ny < height:
            if grid and grid[ny][nx] != 0:
                return False
            return True
        return False

    # Select target based on mode
    target = None
    if mode == 'resource_collection' and resources:
        target = min(resources, key=lambda r: abs(r[0]-x) + abs(r[1]-y))
    elif mode == 'pursuit_evasion' and opponents:
        target = min(opponents, key=lambda o: abs(o[0]-x) + abs(o[1]-y))
    elif mode == 'territory_control' and territory_map:
        if territory_map:
            target = min(territory_map, key=lambda t: abs(t[0]-x) + abs(t[1]-y))

    dx, dy = 0, 0

    if target:
        tx, ty = target
        delta_x = tx - x
        delta_y = ty - y

        # Decide primary axis
        if abs(delta_x) > abs(delta_y):
            dx = 1 if delta_x > 0 else -1 if delta_x < 0 else 0
        elif abs(delta_y) > 0:
            dy = 1 if delta_y > 0 else -1 if delta_y < 0 else 0

        # Check if move is valid
        new_pos = (x + dx, y + dy)
        if not is_valid(new_pos):
            # Try alternatives
            for alt_dx, alt_dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                if (x + alt_dx, y + alt_dy) != (x + dx, y + dy):
                    if is_valid((x + alt_dx, y + alt_dy)):
                        dx, dy = alt_dx, alt_dy
                        break
    else:
        # No target; pick a safe move
        for alt_dx, alt_dy in [(0,1),(0,-1),(1,0),(-1,0),(0,0)]:
            if is_valid((x + alt_dx, y + alt_dy)):
                dx, dy = alt_dx, alt_dy
                break

    # Clamp to -1, 0, 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]

